internal val LOCALE_DISPLAY_NAMES_KM: String =
    "root\u001Faa\u001Dអាហ្វារ\u001Eab\u001Dអាប់ខាហ៊្សាន\u001Eace\u001Dអាកហ៊ីនឺស\u001Eada\u001Dអាដេងមី\u001Eady\u001Dអាឌីហ្គី\u001Eae\u001Dអាវេស្ថាន\u001Eaf\u001Dអាហ្វ្រិកាន\u001Eagq\u001Dអាហ្គីម\u001Eain\u001Dអាយនូ\u001Eak\u001Dអាកាន\u001Eale\u001Dអាលូត\u001Ealt\u001Dអាល់តៃខាងត្បូង\u001Eam\u001Dអាំហារិក\u001Ean\u001Dអារ៉ាហ្គោន\u001Eann\u001Dអូបូឡូ\u001Eanp\u001Dអាហ្គីកា\u001Ear\u001Dអារ៉ាប់\u001Ear_001\u001Dអារ៉ាប់ស្តង់ដារទំនើប\u001Earn\u001Dម៉ាពូឈី\u001Earp\u001Dអារ៉ាប៉ាហូ\u001Ears\u001Dអារ៉ាប់ណាឌី\u001Eas\u001Dអាសាមីស\u001Easa\u001Dអាស៊ូ\u001East\u001Dអាស្ទូរី\u001Eatj\u001Dអាទិកាម៉េក\u001Eav\u001Dអាវ៉ារីក\u001Eawa\u001Dអាវ៉ាឌី\u001Eay\u001Dអីម៉ារ៉ា\u001Eaz\u001Dអាស៊ែបៃហ្សង់\u001Eaz#short\u001Dអាហ្ស៊ែរី\u001Eba\u001Dបាស្គៀ\u001Ebal\u001Dបាលូឈី\u001Eban\u001Dបាលី\u001Ebas\u001Dបាសា\u001Ebe\u001Dបេឡារុស\u001Ebem\u001Dបេមបា\u001Ebez\u001Dបេណា\u001Ebg\u001Dប៊ុលហ្ការី\u001Ebgc\u001Dហារីយ៉ាន់វី\u001Ebgn\u001Dបាឡូជីខាងលិច\u001Ebho\u001Dបូចពូរី\u001Ebi\u001Dប៊ីស្លាម៉ា\u001Ebin\u001Dប៊ីនី\u001Ebla\u001Dស៊ីកស៊ីកា\u001Eblo\u001Dអានី\u001Ebm\u001Dបាម្បារា\u001Ebn\u001Dបង់ក្លា\u001Ebo\u001Dទីបេ\u001Ebr\u001Dប្រ៊ីស្តុន\u001Ebrx\u001Dបូដូ\u001Ebs\u001Dបូស្ន៊ី\u001Ebug\u001Dប៊ុកហ្គី\u001Ebyn\u001Dប្ល៊ីន\u001Eca\u001Dកាតាឡាន\u001Ecay\u001Dខាយូហ្កា\u001Eccp\u001Dចាក់ម៉ា\u001Ece\u001Dឈីឆេន\u001Eceb\u001Dស៊ីប៊ូអាណូ\u001Ecgg\u001Dឈីហ្កា\u001Ech\u001Dឈីម៉ូរ៉ូ\u001Echk\u001Dឈូគី\u001Echm\u001Dម៉ារី\u001Echo\u001Dឆុកតាវ\u001Echp\u001Dឈីប៉េវ៉ាយអិន\u001Echr\u001Dឆេរូគី\u001Echy\u001Dឈីយីនី\u001Eckb\u001Dឃើដភាគកណ្តាល\u001Eclc\u001Dឈីលកូទីន\u001Eco\u001Dកូស៊ីខាន\u001Ecrg\u001Dមីឈីហ្វ\u001Ecrj\u001Dគ្រីខាងកើត​ប៉ែកខាងត្បូង\u001Ecrk\u001Dគ្រីតំបន់វាលរាប\u001Ecrl\u001Dគ្រីខាងកើត​ប៉ែកខាងជើង\u001Ecrm\u001Dមូសគ្រី\u001Ecrr\u001Dអាល់ហ្គនខ្វៀន ខារ៉ូលីណា\u001Ecrs\u001Dសេសេលវ៉ាគ្រីអូល (បារាំង)\u001Ecs\u001Dឆែក\u001Ecsw\u001Dគ្រីតំបន់ភក់ល្បាប់\u001Ecu\u001Dឈើជស្លាវិក\u001Ecv\u001Dឈូវ៉ាស\u001Ecy\u001Dវេល\u001Eda\u001Dដាណឺម៉ាក\u001Edak\u001Dដាកូតា\u001Edar\u001Dដាចវ៉ា\u001Edav\u001Dតៃតា\u001Ede\u001Dអាល្លឺម៉ង់\u001Edgr\u001Dដូគ្រីប\u001Edje\u001Dហ្សាម៉ា\u001Edoi\u001Dដូហ្គ្រី\u001Edsb\u001Dសូប៊ីក្រោម\u001Edua\u001Dឌួលឡា\u001Edv\u001Dទេវីហ៊ី\u001Edyo\u001Dចូឡាហ៊្វុនយី\u001Edz\u001Dដុងខា\u001Edzg\u001Dដាហ្សាហ្គា\u001Eebu\u001Dអេមប៊ូ\u001Eee\u001Dអ៊ីវ\u001Eefi\u001Dអ៊ីហ្វិក\u001Eeka\u001Dអ៊ីកាជុក\u001Eel\u001Dក្រិក\u001Een\u001Dអង់គ្លេស\u001Een_US#short\u001Dអង់គ្លេស (ស.រ.អ.)\u001Eeo\u001Dអេស្ពេរ៉ាន់តូ\u001Ees\u001Dអេស្ប៉ាញ\u001Ees_ES\u001Dអេស្ប៉ាញ (អ៊ឺរ៉ុប)\u001Eet\u001Dអេស្តូនី\u001Eeu\u001Dបាសខ៍\u001Eewo\u001Dអ៊ីវ៉ុនដូ\u001Efa\u001Dភឺសៀន\u001Efa_AF\u001Dដារី\u001Eff\u001Dហ្វ៊ូឡា\u001Efi\u001Dហ្វាំងឡង់\u001Efil\u001Dហ្វ៊ីលីពីន\u001Efj\u001Dហ៊្វីជី\u001Efo\u001Dហ្វារូស\u001Efon\u001Dហ្វ៊ុន\u001Efr\u001Dបារាំង\u001Efrc\u001Dបារាំងកាហ្សង់\u001Efrr\u001Dហ្វ្រ៊ីសៀន​ខាងជើង\u001Efur\u001Dហ៊្វ្រូលាន\u001Efy\u001Dហ្វ្រីស៊ានខាងលិច\u001Ega\u001Dអៀរឡង់\u001Egaa\u001Dហ្គា\u001Egag\u001Dកាគូស\u001Egd\u001Dស្កុតហ្កែលិគ\u001Egez\u001Dជីស\u001Egil\u001Dហ្គីលបឺទ\u001Egl\u001Dហ្កាលីស្យាន\u001Egn\u001Dហ្គូរ៉ានី\u001Egor\u001Dហ្គូរុនតាឡូ\u001Egsw\u001Dអាល្លឺម៉ង (ស្វីស)\u001Egu\u001Dហ្គុយ៉ារ៉ាទី\u001Eguz\u001Dហ្គូស៊ី\u001Egv\u001Dមេន\u001Egwi\u001Dហ្គីចឈីន\u001Eha\u001Dហូសា\u001Ehai\u001Dហៃដា\u001Ehaw\u001Dហាវ៉ៃ\u001Ehax\u001Dហៃដាខាងត្បូង\u001Ehe\u001Dហេប្រឺ\u001Ehi\u001Dហិណ្ឌី\u001Ehil\u001Dហ៊ីលីហ្គេណុន\u001Ehmn\u001Dម៉ុង\u001Ehr\u001Dក្រូអាស៊ី\u001Ehsb\u001Dសូប៊ីលើ\u001Eht\u001Dហៃទី\u001Ehu\u001Dហុងគ្រី\u001Ehup\u001Dហ៊ូប៉ា\u001Ehur\u001Dហាល់កូម៉េឡេម\u001Ehy\u001Dអាមេនី\u001Ehz\u001Dហឺរីរ៉ូ\u001Eia\u001Dអ៊ីនធើលីង\u001Eiba\u001Dអ៊ីបាន\u001Eibb\u001Dអាយប៊ីប៊ីអូ\u001Eid\u001Dឥណ្ឌូណេស៊ី\u001Eie\u001Dអ៊ីនធើលីងវេ\u001Eig\u001Dអ៊ីកបូ\u001Eii\u001Dស៊ីឈាន់យី\u001Eikt\u001Dអ៊ីនុកទីទុត​កាណាដា​ប៉ែកខាងលិច\u001Eilo\u001Dអ៊ីឡូកូ\u001Einh\u001Dអ៊ិនហ្គូស\u001Eio\u001Dអ៊ីដូ\u001Eis\u001Dអ៊ីស្លង់\u001Eit\u001Dអ៊ីតាលី\u001Eiu\u001Dអ៊ីនុកទីទុត\u001Eja\u001Dជប៉ុន\u001Ejbo\u001Dលុចបាន\u001Ejgo\u001Dងុំបា\u001Ejmc\u001Dម៉ាឆាំ\u001Ejv\u001Dជ្វា\u001Eka\u001Dហ្សក​ហ្ស៊ី\u001Ekab\u001Dកាប៊ីឡេ\u001Ekac\u001Dកាឈីន\